// Some portions generated by Claude Code

const test = require('node:test');
const assert = require('node:assert/strict');

const { createQueryBrowserHarness } = require('./query-browser-harness.js');

// Review finding B6 (explain half): Explain adds infer=false only for an enabled, unchecked infer checkbox.
test('Explain does not add infer when the infer control is disabled or absent', () => {
    const harness = createQueryBrowserHarness();
    const testing = harness.context.workbench.query.testing;
    const infer = harness.document.getElementById('infer');

    infer.checked = false;
    assert.equal(new URLSearchParams(testing.serializeExplainFormData('ASK {}', 'Optimized', 'json', 'r-1'))
        .get('infer'), 'false', 'an enabled unchecked checkbox still means no inference');

    infer.disabled = true;
    assert.equal(new URLSearchParams(testing.serializeExplainFormData('ASK {}', 'Optimized', 'json', 'r-2'))
        .has('infer'), false, 'a policy-disabled control is not sent');

    infer.disabled = false;
    infer.parentNode.removeChild(infer);
    harness.document.untrack(infer);
    const form = harness.document.querySelectorAll('form[action="query"]')[0];
    form.formControls = form.formControls.filter((control) => control !== infer);
    assert.equal(new URLSearchParams(testing.serializeExplainFormData('ASK {}', 'Optimized', 'json', 'r-3'))
        .has('infer'), false, 'a page without the control does not send it');
});

function openDiffWithBothPlans(harness) {
    const query = harness.context.workbench.query;
    const plan = { content: 'Plan', format: 'text', error: '' };
    query.setQueryValue('ASK {}');
    harness.click('explain-trigger');
    harness.pendingExplainRequests[0].resolve(plan);
    query.toggleCompareMode();
    harness.pendingExplainRequests[1].resolve(plan);
    harness.advanceTimers(1000);
    query.openDiffModal('query-actions-diff');
}

// Review finding B2: a parked (suspended) Query page must not leave document-level state behind for the next page.
test('suspending the Query page releases results full screen, the Diff dialog and editor full screen', () => {
    const harness = createQueryBrowserHarness({ serverRequestIds: ['request-1', 'request-2', 'request-3'] });
    const cleanup = harness.runPageLoad();
    openDiffWithBothPlans(harness);
    assert.equal(harness.document.body.style.overflow, 'hidden', 'the open Diff dialog locks the page');

    const results = harness.document.getElementById('query-results');
    const control = harness.registerElement('button', { attributes: { 'data-result-fullscreen-enabled': 'true' } });
    results.appendChild(control);
    harness.context.workbench.resultFullscreen.set(results, control, true, false);
    assert.equal(harness.document.body.classList.contains('query-results-fullscreen-active'), true);
    const editor = harness.yasqeState.instances.query;
    editor.setOption('fullScreen', true);

    cleanup.suspend();
    assert.equal(harness.document.body.classList.contains('query-results-fullscreen-active'), false,
        'results full screen does not lock the next page');
    assert.notEqual(harness.document.body.style.overflow, 'hidden', 'the Diff dialog does not lock the next page');
    assert.equal(harness.hasClass('query-diff-modal', 'query-diff-modal--open'), false);
    assert.equal(editor.getOption('fullScreen'), false, 'editor full screen does not cover the next page');

    cleanup.resume();
    cleanup();
});

test('disposing the Query page leaves editor full screen', () => {
    const harness = createQueryBrowserHarness();
    const cleanup = harness.runPageLoad();
    const editor = harness.yasqeState.instances.query;
    editor.setOption('fullScreen', true);
    cleanup();
    assert.equal(editor.getOption('fullScreen'), false);
    assert.equal(editor.closed, true);
});

// Review finding B4: explanation updates arriving while the page is parked must not re-apply compare chrome.
test('a parked Query page in compare mode does not re-apply compare chrome when an explanation arrives', () => {
    const harness = createQueryBrowserHarness({ serverRequestIds: ['request-1', 'request-2', 'request-3'] });
    const cleanup = harness.runPageLoad();
    const query = harness.context.workbench.query;
    const plan = { content: 'Plan', format: 'text', error: '' };
    const resizeBefore = harness.window.listenerCount('resize');
    query.setQueryValue('ASK {}');
    harness.click('explain-trigger');
    harness.pendingExplainRequests[0].resolve(plan);
    query.toggleCompareMode();
    assert.equal(harness.document.body.classList.contains('query-compare-mode'), true);
    assert.equal(harness.pendingExplainRequests.length, 2, 'a compare explanation is running');

    cleanup.suspend();
    assert.equal(harness.document.body.classList.contains('query-compare-mode'), false);
    harness.pendingExplainRequests[1].resolve(plan);
    harness.advanceTimers(1000);
    assert.equal(harness.document.body.classList.contains('query-compare-mode'), false,
        'the page shown instead keeps its menu');
    assert.equal(harness.document.body.classList.contains('query-compare-nav-open'), false);
    assert.equal(harness.document.getElementById('navigation').style.transform || '', '');
    assert.equal(harness.window.listenerCount('resize'), resizeBefore, 'no window listener is added while parked');

    cleanup.resume();
    assert.equal(harness.document.body.classList.contains('query-compare-mode'), true, 'resume shows compare mode again');
    cleanup();
});

// Review finding B8: a query opened from the URL keeps a literal '+' (%2B) and reads '+' as a space.
test('the Query page reads its query from the URL with encoded plus signs intact', () => {
    const query = 'SELECT (1+1 AS ?x) WHERE { BIND("a b" AS ?y) }';
    const harness = createQueryBrowserHarness({
        href: 'http://localhost:8080/rdf4j-workbench/repositories/test/query?query='
            + encodeURIComponent(query) + '&ref=text',
        query: ''
    });
    harness.runPageLoad();
    assert.equal(harness.context.workbench.query.getQueryValue(), query);
});

test('the Query page reads form-encoded spaces and survives a malformed escape in the URL', () => {
    const spaces = createQueryBrowserHarness({
        href: 'http://localhost:8080/rdf4j-workbench/repositories/test/query?query=ASK+%7B%7D', query: ''
    });
    spaces.runPageLoad();
    assert.equal(spaces.context.workbench.query.getQueryValue(), 'ASK {}');

    const malformed = createQueryBrowserHarness({
        href: 'http://localhost:8080/rdf4j-workbench/repositories/test/query?query=ASK+%7B%7D+%ZZ', query: ''
    });
    malformed.runPageLoad();
    assert.equal(malformed.context.workbench.query.getQueryValue(), 'ASK+%7B%7D+%ZZ'.replace(/\+/g, ' '));
});

// Round 2 (R20): a hand-typed query link may hold an unencoded '#': the browser takes it as the fragment, and the query
// is read from the whole address, as before the '+' fix.
test('the Query page reads a query whose unencoded "#" the browser took as the fragment', () => {
    const harness = createQueryBrowserHarness({
        href: 'http://localhost:8080/rdf4j-workbench/repositories/test/query?query=PREFIX%20ex:%20%3Chttp://ex.org/ns'
            + '#%3E%20ASK%20%7B%7D',
        query: ''
    });
    harness.runPageLoad();
    assert.equal(harness.context.workbench.query.getQueryValue(), 'PREFIX ex: <http://ex.org/ns#> ASK {}');
});

// Review finding B17: a PREFIX declared after other text on its line is still a declaration.
test('Insert prefixes finds declarations anywhere, but not in comments or strings', () => {
    const harness = createQueryBrowserHarness({ sparqlNamespaces: {
        ex: 'http://example.com/', foaf: 'http://xmlns.com/foaf/0.1/', rdfs: 'http://www.w3.org/2000/01/rdf-schema#',
        '': 'http://default.example/'
    } });
    harness.runPageLoad();
    const query = harness.context.workbench.query;
    query.setQueryValue('BASE <http://base/> PREFIX ex: <http://example.com/> PREFIX : <http://default.example/>\n'
        + '# PREFIX foaf: <http://xmlns.com/foaf/0.1/>\n'
        + 'SELECT ?prefix WHERE { ?s ex:p "PREFIX rdfs: <x>" . FILTER(?prefix < 3) }');

    query.insertPrefixes();
    const lines = query.getQueryValue().split('\n');
    assert.deepEqual(lines.slice(0, 2), ['PREFIX foaf: <http://xmlns.com/foaf/0.1/>',
        'PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>'],
        'prefixes only mentioned in a comment or a string are inserted');
    assert.equal((query.getQueryValue().match(/PREFIX ex:/g) || []).length, 1, 'ex is declared after BASE');
    assert.equal((query.getQueryValue().match(/PREFIX :/g) || []).length, 1, 'the default prefix is declared');

    query.setQueryValue('SELECT * { ?s ?p """long\nPREFIX ex: <x> \\""" """, \'it\\\'s PREFIX foaf: <y>\' }');
    query.insertPrefixes();
    const inserted = query.getQueryValue().split('SELECT')[0];
    assert.match(inserted, /^PREFIX ex: <http:\/\/example\.com\/>$/m,
        'a declaration inside a long string is no declaration');
    assert.match(inserted, /^PREFIX foaf: <http:\/\/xmlns\.com\/foaf\/0\.1\/>$/m,
        'nor one inside a short string with an escaped quote');
});

// Review finding B16: leaving the Query page while an explanation runs asks the server to stop it.
test('disposing the Query page cancels a running explanation on the server, at its own endpoint', () => {
    const harness = createQueryBrowserHarness({ serverRequestIds: ['request-1'] });
    const cleanup = harness.runPageLoad();
    harness.context.workbench.query.setQueryValue('ASK {}');
    harness.click('explain-trigger');
    assert.equal(harness.requestsByAction('explain').length, 1);
    // The router shows the next page's address before it disposes this one.
    harness.document.location.href = 'http://localhost:8080/rdf4j-workbench/repositories/other/summary';

    cleanup();
    const cancels = harness.requestsByAction('cancel-explain');
    assert.equal(cancels.length, 1, 'the running explanation is cancelled');
    assert.equal(cancels[0].params.get('explain-request-id'), 'request-1');
    assert.equal(cancels[0].options.url, 'http://localhost:8080/rdf4j-workbench/repositories/test/query',
        'at the Query page\'s own repository');
    assert.equal(harness.requestsByAction('explain')[0].aborted, true);
});

test('a Query page unloaded while an explanation runs cancels it with one keepalive request', () => {
    const harness = createQueryBrowserHarness({ serverRequestIds: ['request-1'] });
    const fetches = [];
    harness.window.fetch = (url, init) => { fetches.push({ url, init }); return Promise.resolve({ ok: true }); };
    const cleanup = harness.runPageLoad();
    harness.context.workbench.query.setQueryValue('ASK {}');
    harness.click('explain-trigger');
    // Round 2 (R11): pagehide runs while the document is still visible; the route is disposed with reason 'pagehide'.
    assert.equal(harness.document.visibilityState === 'hidden', false);

    cleanup('pagehide');
    assert.equal(harness.requestsByAction('cancel-explain').length, 0, 'no retrying request that dies with the page');
    assert.equal(fetches.length, 1);
    assert.equal(fetches[0].url, 'http://localhost:8080/rdf4j-workbench/repositories/test/query');
    assert.equal(fetches[0].init.keepalive, true);
    assert.equal(fetches[0].init.body, 'action=cancel-explain&explain-request-id=request-1');
});

test('a page being unloaded falls back to the retrying cancellation without fetch, and survives a refused fetch', () => {
    const withoutFetch = createQueryBrowserHarness({ serverRequestIds: ['request-1'] });
    const cleanup = withoutFetch.runPageLoad();
    withoutFetch.context.workbench.query.setQueryValue('ASK {}');
    withoutFetch.click('explain-trigger');
    cleanup('pagehide');
    assert.equal(withoutFetch.requestsByAction('cancel-explain').length, 1);

    const refused = createQueryBrowserHarness({ serverRequestIds: ['request-2'] });
    refused.window.fetch = () => { throw new Error('Refused while unloading'); };
    const refusedCleanup = refused.runPageLoad();
    refused.context.workbench.query.setQueryValue('ASK {}');
    refused.click('explain-trigger');
    assert.doesNotThrow(() => refusedCleanup('pagehide'));
});

// Round 2 (R11): Firefox and Safari stop a page's requests before its pagehide; the explanation request then fails
// without an answer (status 0) while the server still runs it, so it is cancelled with one keepalive request.
test('an explanation request that fails without an answer is cancelled on the server with a keepalive request', () => {
    const harness = createQueryBrowserHarness({ serverRequestIds: ['request-1'] });
    const fetches = [];
    harness.window.fetch = (url, init) => { fetches.push({ url, init }); return Promise.resolve({ ok: true }); };
    const cleanup = harness.runPageLoad();
    harness.context.workbench.query.setQueryValue('ASK {}');
    harness.click('explain-trigger');
    const explanation = harness.pendingExplainRequests[harness.pendingExplainRequests.length - 1];
    explanation.jqXHR.status = 0;
    explanation.reject('error', '');
    assert.equal(fetches.length, 1);
    assert.equal(fetches[0].init.keepalive, true);
    assert.equal(fetches[0].init.body, 'action=cancel-explain&explain-request-id=request-1');

    cleanup('pagehide');
    assert.equal(fetches.length, 1, 'the explanation is cancelled once');
    assert.equal(harness.requestsByAction('cancel-explain').length, 0);
});

test('an explanation the server answered with an error, or the page aborted, is not cancelled again', () => {
    const harness = createQueryBrowserHarness({ serverRequestIds: ['request-1', 'request-2'] });
    const fetches = [];
    harness.window.fetch = (url, init) => { fetches.push({ url, init }); return Promise.resolve({ ok: true }); };
    const cleanup = harness.runPageLoad();
    harness.context.workbench.query.setQueryValue('ASK {}');
    harness.click('explain-trigger');
    const answered = harness.pendingExplainRequests[harness.pendingExplainRequests.length - 1];
    answered.jqXHR.status = 500;
    answered.reject('error', 'Internal Server Error');
    assert.equal(fetches.length, 0);
    cleanup();
});

test('the Query page endpoint is resolved with URL against the document base, or left relative', () => {
    const resolved = createQueryBrowserHarness({ serverRequestIds: ['request-1'] });
    resolved.context.URL = URL;
    resolved.document.baseURI = 'http://localhost:8080/rdf4j-workbench/repositories/based/query?x=1';
    const cleanup = resolved.runPageLoad();
    resolved.context.workbench.query.setQueryValue('ASK {}');
    resolved.click('explain-trigger');
    cleanup();
    assert.equal(resolved.requestsByAction('cancel-explain')[0].options.url,
        'http://localhost:8080/rdf4j-workbench/repositories/based/query');

    const unresolved = createQueryBrowserHarness({ serverRequestIds: ['request-2'] });
    unresolved.context.URL = URL;
    unresolved.document.baseURI = 'not a URL';
    const unresolvedCleanup = unresolved.runPageLoad();
    unresolved.context.workbench.query.setQueryValue('ASK {}');
    unresolved.click('explain-trigger');
    unresolvedCleanup();
    assert.equal(unresolved.requestsByAction('cancel-explain')[0].options.url, 'query');
});

// Review finding B18: a cancellation goes to the repository that runs the query. Round 2 (R6): a 404 is retried like
// any other failure (GH-5904: a replica that does not run the query, or a cancellation that overtook its registration).
test('a query cancellation is posted to the given endpoint and retried there when the server answers 404', () => {
    const harness = createQueryBrowserHarness({
        onAjaxRequest(request) {
            if (request.action === 'cancel-query') {
                request.jqXHR.status = 404;
                request.reject('error', 'Not Found');
            }
        }
    });
    harness.context.workbench.query.cancelServerQuery('query-1',
        'http://localhost:8080/rdf4j-workbench/repositories/shelved/query');
    const cancels = harness.requestsByAction('cancel-query');
    assert.equal(cancels.length, 21, 'a 404 is retried, 20 times at most');
    assert.deepEqual([...new Set(cancels.map((cancel) => cancel.options.url))],
        ['http://localhost:8080/rdf4j-workbench/repositories/shelved/query'], 'every retry goes to the same endpoint');
});

// Review finding B10 (server contract): the server refuses a private save by an anonymous user with a JSON message;
// the old client guard (#selected-user) is gone, so the save feedback must show that message.
test('a refused save shows the server\'s message', () => {
    const harness = createQueryBrowserHarness();
    const testing = harness.context.workbench.query.testing;
    testing.ajaxSave(false);
    const request = harness.ajaxRequests[harness.ajaxRequests.length - 1];
    request.jqXHR.status = 400;
    request.jqXHR.responseText = '{"error":"Private saved queries require a signed-in user"}';
    request.reject('error', 'Bad Request');
    assert.equal(harness.getText('save-feedback'), 'Save failed: Private saved queries require a signed-in user');
    assert.equal(harness.hasClass('save-feedback', 'error'), true);

    testing.ajaxSave(false);
    harness.ajaxRequests[harness.ajaxRequests.length - 1].reject('error', 'Forbidden');
    assert.match(harness.getText('save-feedback'), /Save Request Failed/, 'without a message the status is shown');
});

test('Explain does not send an explanation timeout when the query timeout control is disabled', () => {
    const harness = createQueryBrowserHarness({ queryTimeout: '60' });
    const testing = harness.context.workbench.query.testing;
    harness.document.getElementById('explanation-timeout').value = '5';
    assert.deepEqual(new URLSearchParams(testing.serializeExplainFormData('ASK {}', 'Optimized', 'json', 'r-1'))
        .getAll('query-timeout'), ['5']);

    harness.document.getElementById('query-timeout').disabled = true;
    assert.equal(new URLSearchParams(testing.serializeExplainFormData('ASK {}', 'Optimized', 'json', 'r-2'))
        .has('query-timeout'), false, 'a policy-disabled timeout is not sent, not even as the explanation timeout');
});
